const latestFinanceBalances = `-- name: LatestFinanceBalances :many
SELECT DISTINCT ON (b.account_id) b.account_id, b.as_of, b.balance_cents
FROM finance_balances b JOIN finance_accounts a ON a.id = b.account_id
WHERE a.workspace_id = $1 AND a.user_id = $2
ORDER BY b.account_id, b.as_of DESC
`

type LatestFinanceBalancesParams struct {
	WorkspaceID uuid.UUID
	UserID      uuid.UUID
}

func (q *Queries) LatestFinanceBalances(ctx context.Context, arg LatestFinanceBalancesParams) ([]FinanceBalance, error) {
	rows, err := q.db.Query(ctx, latestFinanceBalances, arg.WorkspaceID, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []FinanceBalance{}
	for rows.Next() {
		var i FinanceBalance
		if err := rows.Scan(&i.AccountID, &i.AsOf, &i.BalanceCents); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

