const unlinkFinanceTransfer = `-- name: UnlinkFinanceTransfer :exec
UPDATE finance_transactions SET transfer_id = NULL, category = NULL, category_source = NULL
WHERE transfer_id = $1 AND category_source = 'match'
`

// The other side of a transfer the person re-categorized goes back to review.
func (q *Queries) UnlinkFinanceTransfer(ctx context.Context, id *uuid.UUID) error {
	_, err := q.db.Exec(ctx, unlinkFinanceTransfer, id)
	return err
}

const upsertFinanceBalance = `-- name: UpsertFinanceBalance :exec
INSERT INTO finance_balances (account_id, as_of, balance_cents) VALUES ($1, $2, $3)
ON CONFLICT (account_id, as_of) DO UPDATE SET balance_cents = EXCLUDED.balance_cents
`

